import { PlaneGeometry, Mesh, Object3D } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  // Dimensions based on atlas region (512x320) with base width = 1.2 units
  const baseWidth = 1.2;
  const regionAspect = 512 / 320; // 1.6
  const width = baseWidth;
  const height = width / regionAspect; // 0.75

  // Load the texture (cached)
  const tex = ctx.textureLoader.load(config.assets.imageUrl);

  // UV offset for atlas region: assume atlas is 512x512
  const atlasWidth = 512;
  const atlasHeight = 512;
  const regionX = 0, regionY = 0, regionW = 512, regionH = 320;
  tex.repeat.set(regionW / atlasWidth, regionH / atlasHeight);
  tex.offset.set(regionX / atlasWidth, 1 - (regionY + regionH) / atlasHeight);

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    map: texture(tex), // .map node
    transparent: true,
    depthWrite: false,
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.set(config.scene.position.x, config.scene.position.y, config.scene.position.z);

  // Billboard behavior: always face camera
  mesh.userData.handlers = {
    onBeforeRender: (camera) => {
      mesh.lookAt(camera.position);
    }
  };

  // Cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    tex.dispose();
  };

  return mesh;
}
